node --input-type=module -e "
import fs from 'node:fs';
import path from 'node:path';
const root = 'D:/\\.1 Work Stations/RootMC/Server Handoffs/Ava Ivy/data/ecoflow/history';
const sns = ['R331ZAB5SG6S2858','R331ZAB5SG755642','R621ZA16XH6K1155'];
const nick = { R331ZAB5SG6S2858:'cucumbers', R331ZAB5SG755642:'Delta2-B', R621ZA16XH6K1155:'shackas' };
// Hawaii morning Aug 2 2026: 06:00-12:00 HST = 16:00-22:00 UTC
const morningStart = Date.parse('2026-08-02T16:00:00.000Z');
const morningEnd = Date.parse('2026-08-02T22:00:00.000Z');
const now = Date.now();
const end = Math.min(now, morningEnd);
function loadMinutes(sn) {
  const f = path.join(root, sn + '-minutes.jsonl');
  if (!fs.existsSync(f)) return [];
  return fs.readFileSync(f,'utf8').trim().split(/\n+/).filter(Boolean).map(l => { try { return JSON.parse(l); } catch { return null; } }).filter(Boolean);
}
const bySn = {};
let siteSamples = [];
for (const sn of sns) {
  const rows = loadMinutes(sn).filter(r => {
    const t = r.minute || r.at;
    return t >= morningStart && t <= end;
  });
  const solarVals = rows.map(r => Number(r.solarW)).filter(n => Number.isFinite(n));
  const avg = solarVals.length ? solarVals.reduce((a,b)=>a+b,0)/solarVals.length : null;
  const max = solarVals.length ? Math.max(...solarVals) : null;
  const min = solarVals.length ? Math.min(...solarVals) : null;
  const latest = rows.at(-1);
  bySn[sn] = { nick: nick[sn], n: solarVals.length, avg, max, min, latestSolar: latest?.solarW, latestAt: latest?.at || latest?.minute };
  console.log(nick[sn], { n: solarVals.length, avg: avg?.toFixed(1), max, min, sample: rows.slice(0,2), last: rows.at(-1) });
}
// site total per minute: sum solar across devices for same minute
const minuteMap = new Map();
for (const sn of sns) {
  for (const r of loadMinutes(sn)) {
    const t = r.minute || (Math.floor((r.at||0)/60000)*60000);
    if (t < morningStart || t > end) continue;
    const cur = minuteMap.get(t) || { solar: 0, devices: 0 };
    if (Number.isFinite(Number(r.solarW))) { cur.solar += Number(r.solarW); cur.devices += 1; }
    minuteMap.set(t, cur);
  }
}
const siteVals = [...minuteMap.values()].map(v => v.solar);
const siteAvg = siteVals.length ? siteVals.reduce((a,b)=>a+b,0)/siteVals.length : null;
console.log('SITE', { minutes: siteVals.length, avgW: siteAvg?.toFixed(1), max: siteVals.length?Math.max(...siteVals):null, windowStart: new Date(morningStart).toISOString(), windowEnd: new Date(end).toISOString(), now: new Date(now).toISOString() });
// also check raw jsonl density
for (const sn of sns) {
  const f = path.join(root, sn + '.jsonl');
  const lines = fs.readFileSync(f,'utf8').trim().split(/\n+/).filter(Boolean);
  console.log(nick[sn]+' raw samples', lines.length, 'first', lines[0]?.slice(0,120), 'last', lines.at(-1)?.slice(0,120));
}
"

