input.contents:
/**
 * Host site (Mountain View, HI) — solar + localized NWS weather/hazards.
 * Used in hourly snapshot enrichment and ops power talk.
 * Weather: api.weather.gov (NWS) — same storm/hazard rail RootRecord Weather Manager uses.
 * Optional: WEATHER_API_PUBLIC_URL / api-weather.rootrecord.info when routes exist.
 */
import fs from "node:fs";
import path from "node:path";
import { storePaths } from "./store.mjs";
import {
  refreshEcoFlow,
  loadEcoSnapshot,
  summarizeMorningSolar,
  ECO_NICKNAMES,
} from "./ecoflow.mjs";
import { loadSolarProfile } from "./solarProfile.mjs";

const NWS_UA = "RootMC Ava (rootmc.net; host-site hourly)";
const DEFAULT_SITE = {
  id: "host-site-mountain-view-hi-v1",
  label: "Hawaii Mountain View - Starlink / solar server",
  locale: "Mountain View, HI",
  lat: 19.5558,
  lon: -155.1069,
  tz_offset_hours: -10,
};

function sitePath() {
  return path.join(storePaths().dir, "host-site.json");
}

function telemetryPath() {
  return path.join(storePaths().dir, "host-site-telemetry.json");
}

export function loadHostSite() {
  try {
    if (!fs.existsSync(sitePath())) return { ...DEFAULT_SITE };
    return { ...DEFAULT_SITE, ...JSON.parse(fs.readFileSync(sitePath(), "utf8")) };
  } catch {
    return { ...DEFAULT_SITE };
  }
}

async function nwsJson(url) {
  const res = await fetch(url, {
    headers: { Accept: "application/geo+json,application/json", "User-Agent": NWS_UA },
  });
  const text = await res.text();
  let data = null;
  try {
    data = text ? JSON.parse(text) : null;
  } catch {
    data = null;
  }
  if (!res.ok) {
    throw new Error(`nws ${res.status}: ${text.slice(0, 120)}`);
  }
  return data;
}

/**
 * Localized forecast + active alerts for host site (NWS).
 */
export async function fetchHostSiteWeather(site = loadHostSite()) {
  const lat = Number(site.lat);
  const lon = Number(site.lon);
  if (!Number.isFinite(lat) || !Number.isFinite(lon)) {
    return { ok: false, detail: "bad_coords" };
  }
  const points = await nwsJson(
    `https://api.weather.gov/points/${lat.toFixed(4)},${lon.toFixed(4)}`,
  );
  const forecastUrl = points?.properties?.forecast;
  const city =
    points?.properties?.relativeLocation?.properties?.city || site.locale;
  const state =
    points?.properties?.relativeLocation?.properties?.state || "HI";

  let period = null;
  if (forecastUrl) {
    const forecast = await nwsJson(forecastUrl);
    period = forecast?.properties?.periods?.[0] || null;
  }

  let alerts = [];
  try {
    const alertData = await nwsJson(
      `https://api.weather.gov/alerts/active?point=${lat.toFixed(4)},${lon.toFixed(4)}`,
    );
    alerts = (alertData?.features || [])
      .map((f) => ({
        event: f?.properties?.event || "Alert",
        severity: f?.properties?.severity || "",
        headline: String(f?.properties?.headline || "").slice(0, 160),
      }))
      .slice(0, 5);
  } catch {
    alerts = [];
  }

  return {
    ok: true,
    source: "NWS",
    city,
    state,
    period: period
      ? {
          name: period.name,
          temp: period.temperature,
          unit: period.temperatureUnit || "F",
          wind: period.windSpeed,
          short: period.shortForecast,
        }
      : null,
    alerts,
    fetchedAt: new Date().toISOString(),
  };
}

function snLabel(sn) {
  for (const [nick, serial] of Object.entries(ECO_NICKNAMES)) {
    if (String(serial) === String(sn) && !/^(delta-2|river)/i.test(nick)) {
      return nick;
    }
  }
  return sn.slice(-6);
}

export function formatSolarLines(snap, morning = null) {
  const lines = [];
  const per = snap?.perSn || {};
  let solarTotal = 0;
  for (const [sn, v] of Object.entries(per)) {
    if (!v?.ok) continue;
    if (v.solarW != null) solarTotal += Number(v.solarW) || 0;
    const bits = [
      v.soc != null ? `SOC ${v.soc}%` : null,
      v.solarW != null ? `solar ${Math.round(v.solarW)}W` : null,
      v.outW != null ? `out ${Math.round(v.outW)}W` : null,
    ].filter(Boolean);
    lines.push(`- **${snLabel(sn)}**: ${bits.join(" / ") || "ok"}`);
  }
  if (snap?.batteryPct != null) {
    lines.unshift(`- **Bank:** ${snap.batteryPct}% overall`);
  }
  if (solarTotal > 0) {
    lines.push(`- **Site solar in now:** ~${Math.round(solarTotal)}W`);
  }
  if (morning?.siteAvgW != null) {
    lines.push(
      `- **Morning solar avg (sampled):** ~${Math.round(morning.siteAvgW)}W` +
        (morning.note && morning.note !== "ok" ? ` (${morning.note})` : ""),
    );
  }
  const solar = loadSolarProfile();
  lines.push(
    `- **Array:** ${solar?.panels?.count ?? 10} panels / ${solar?.panels?.circuits ?? 2} circuits / ${solar?.batteries?.count ?? 3} batteries`,
  );
  return lines;
}

export function formatWeatherLines(weather) {
  if (!weather?.ok) {
    return ["- Weather unavailable right now"];
  }
  const lines = [];
  const p = weather.period;
  if (p) {
    lines.push(
      `- **Now (${p.name}):** ${p.temp}${p.unit} - ${p.short}` +
        (p.wind ? ` - wind ${p.wind}` : ""),
    );
  }
  lines.push(`- **Source:** ${weather.source || "NWS"} (${weather.city || "?"}, ${weather.state || "HI"})`);
  if (weather.alerts?.length) {
    for (const a of weather.alerts) {
      lines.push(
        `- **HAZARD:** ${a.event}${a.severity ? ` (${a.severity})` : ""}${a.headline ? ` - ${a.headline}` : ""}`,
      );
    }
  } else {
    lines.push("- **Hazards:** none active (NWS)");
  }
  return lines;
}

/**
 * Full host-site block for Discord (ASCII-safe punctuation).
 */
export async function buildHostSiteHourlyBlock({ refreshPower = true } = {}) {
  const site = loadHostSite();
  let snap = loadEcoSnapshot();
  if (refreshPower) {
    try {
      snap = await refreshEcoFlow();
    } catch {
      snap = loadEcoSnapshot();
    }
  }
  const morning = summarizeMorningSolar({
    tzOffsetHours: site.tz_offset_hours ?? -10,
  });
  let weather;
  try {
    weather = await fetchHostSiteWeather(site);
  } catch (err) {
    weather = { ok: false, detail: err.message };
  }

  const payload = {
    site,
    solar: {
      batteryPct: snap?.batteryPct ?? null,
      perSn: snap?.perSn || {},
      morningAvgW: morning.siteAvgW ?? null,
      morningNote: morning.note || null,
    },
    weather,
    updatedAt: new Date().toISOString(),
  };
  try {
    fs.mkdirSync(storePaths().dir, { recursive: true });
    fs.writeFileSync(telemetryPath(), JSON.stringify(payload, null, 2), "utf8");
  } catch {
    /* ignore */
  }

  const lines = [
    `**Host site** - ${site.label || site.locale}`,
    `Starlink + solar server · ${site.locale}`,
    "",
    "**Solar / EcoFlow**",
    ...formatSolarLines(snap, morning),
    "",
    "**Local weather (NWS)**",
    ...formatWeatherLines(weather),
  ];
  return {
    content: lines.join("\n"),
    payload,
  };
}

export function loadHostSiteTelemetry() {
  try {
    if (!fs.existsSync(telemetryPath())) return null;
    return JSON.parse(fs.readFileSync(telemetryPath(), "utf8"));
  } catch {
    return null;
  }
}

/**
 * Push telemetry to api.rootmc.net when workstation key present (Worker hourly reads it).
 */
export async function pushHostSiteTelemetry(env = {}, payload = null) {
  const key = String(
    env.ROOTMC_DEV_WORKSTATION_KEY ||
      process.env.ROOTMC_DEV_WORKSTATION_KEY ||
      process.env.ROOTMC_INTERNAL_API_KEY ||
      "",
  ).trim();
  if (!key) return { ok: false, detail: "no_workstation_key" };
  const body = payload || loadHostSiteTelemetry();
  if (!body) return { ok: false, detail: "no_payload" };
  const base = String(
    process.env.AVA_API_BASE || process.env.ROOTMC_API_BASE || "https://api.rootmc.net",
  ).replace(/\/$/, "");
  try {
    const res = await fetch(`${base}/api/rootmc/host-site/telemetry`, {
      method: "POST",
      headers: {
        Accept: "application/json",
        "Content-Type": "application/json",
        "User-Agent": "AvaIvyRootMC/0.5",
        "X-RootMC-Dev-Key": key,
      },
      body: JSON.stringify(body),
    });
    const text = await res.text();
    let data = null;
    try {
      data = text ? JSON.parse(text) : null;
    } catch {
      data = { raw: text.slice(0, 200) };
    }
    if (!res.ok) {
      return { ok: false, status: res.status, detail: data?.detail || text.slice(0, 160) };
    }
    return { ok: true, data };
  } catch (err) {
    return { ok: false, detail: err.message };
  }
}

/**
 * Host-site telemetry (Mountain View HI solar + NWS weather) for hourly snapshots.
 * Ava POSTs via X-RootMC-Dev-Key; hourly Discord post GETs latest.
 */
import type { D1Database } from "@cloudflare/workers-types";

import { json } from "./http-json";

export type HostSiteEnv = {
  DB: D1Database;
  ROOTMC_DEV_WORKSTATION_KEY?: string;
  ROOTMC_INTERNAL_API_KEY?: string;
};

const NWS_UA = "RootMC Hourly (api.rootmc.net; host-site)";
const DEFAULT_LAT = 19.5558;
const DEFAULT_LON = -155.1069;

function str(v: unknown): string {
  return String(v ?? "").trim();
}

function workstationKeyOk(env: HostSiteEnv, req: Request): boolean {
  const key = str(req.headers.get("X-RootMC-Dev-Key") || req.headers.get("x-rootmc-dev-key"));
  if (!key) return false;
  const a = str(env.ROOTMC_DEV_WORKSTATION_KEY);
  const b = str(env.ROOTMC_INTERNAL_API_KEY);
  return Boolean((a && key === a) || (b && key === b));
}

async function ensureTable(db: D1Database): Promise<void> {
  await db
    .prepare(
      `CREATE TABLE IF NOT EXISTS rootmc_host_site_telemetry (
         host_key TEXT PRIMARY KEY,
         payload_json TEXT NOT NULL,
         updated_at TEXT NOT NULL
       )`,
    )
    .run();
}

export async function readHostSiteTelemetry(
  db: D1Database,
  hostKey = "primary",
): Promise<Record<string, unknown> | null> {
  try {
    await ensureTable(db);
    const row = await db
      .prepare(
        `SELECT payload_json, updated_at FROM rootmc_host_site_telemetry WHERE host_key = ? LIMIT 1`,
      )
      .bind(hostKey)
      .first<{ payload_json: string; updated_at: string }>();
    if (!row?.payload_json) return null;
    const payload = JSON.parse(row.payload_json) as Record<string, unknown>;
    return { ...payload, _updated_at: row.updated_at };
  } catch {
    return null;
  }
}

async function nwsJson(url: string): Promise<any> {
  const res = await fetch(url, {
    headers: { Accept: "application/geo+json,application/json", "User-Agent": NWS_UA },
  });
  if (!res.ok) throw new Error(`nws ${res.status}`);
  return res.json();
}

/** Live NWS forecast + alerts for Mountain View, HI (or telemetry coords). */
export async function fetchNwsHostWeather(lat = DEFAULT_LAT, lon = DEFAULT_LON) {
  const points = await nwsJson(
    `https://api.weather.gov/points/${lat.toFixed(4)},${lon.toFixed(4)}`,
  );
  const forecastUrl = points?.properties?.forecast as string | undefined;
  const city = points?.properties?.relativeLocation?.properties?.city || "Mountain View";
  const state = points?.properties?.relativeLocation?.properties?.state || "HI";
  let period: any = null;
  if (forecastUrl) {
    const forecast = await nwsJson(forecastUrl);
    period = forecast?.properties?.periods?.[0] || null;
  }
  let alerts: Array<{ event: string; severity: string; headline: string }> = [];
  try {
    const alertData = await nwsJson(
      `https://api.weather.gov/alerts/active?point=${lat.toFixed(4)},${lon.toFixed(4)}`,
    );
    alerts = (alertData?.features || [])
      .map((f: any) => ({
        event: String(f?.properties?.event || "Alert"),
        severity: String(f?.properties?.severity || ""),
        headline: String(f?.properties?.headline || "").slice(0, 140),
      }))
      .slice(0, 5);
  } catch {
    alerts = [];
  }
  return {
    ok: true,
    source: "NWS",
    city,
    state,
    period: period
      ? {
          name: String(period.name || ""),
          temp: period.temperature,
          unit: String(period.temperatureUnit || "F"),
          wind: String(period.windSpeed || ""),
          short: String(period.shortForecast || ""),
        }
      : null,
    alerts,
  };
}

export async function buildHostSiteHourlySection(
  env: HostSiteEnv,
): Promise<{ content: string; detail: string }> {
  const telem = await readHostSiteTelemetry(env.DB, "primary");
  const site = (telem?.site as Record<string, unknown>) || {};
  const lat = Number(site.lat ?? DEFAULT_LAT);
  const lon = Number(site.lon ?? DEFAULT_LON);

  let weather: any = telem?.weather;
  try {
    // Prefer fresh NWS each hour (storm/hazard rail)
    weather = await fetchNwsHostWeather(lat, lon);
  } catch (e) {
    if (!weather?.ok) {
      weather = { ok: false, detail: e instanceof Error ? e.message : String(e) };
    }
  }

  const solar = (telem?.solar as Record<string, unknown>) || {};
  const perSn = (solar.perSn as Record<string, any>) || {};
  const solarLines: string[] = [];
  if (solar.batteryPct != null) {
    solarLines.push(`\u2022 **Bank:** ${solar.batteryPct}%`);
  }
  let solarTotal = 0;
  for (const [sn, v] of Object.entries(perSn)) {
    if (!v || typeof v !== "object" || !v.ok) continue;
    if (v.solarW != null) solarTotal += Number(v.solarW) || 0;
    const label = sn.slice(-6);
    const bits = [
      v.soc != null ? `SOC ${v.soc}%` : null,
      v.solarW != null ? `solar ${Math.round(Number(v.solarW))}W` : null,
    ].filter(Boolean);
    solarLines.push(`\u2022 **${label}:** ${bits.join(" / ")}`);
  }
  if (solarTotal > 0) {
    solarLines.push(`\u2022 **Site solar in:** ~${Math.round(solarTotal)}W`);
  }
  if (solar.morningAvgW != null) {
    solarLines.push(`\u2022 **Morning avg:** ~${Math.round(Number(solar.morningAvgW))}W`);
  }
  if (!solarLines.length) {
    solarLines.push(`\u2022 _Solar telemetry pending (Ava sync)_`);
  }

  const wxLines: string[] = [];
  if (weather?.period) {
    const p = weather.period;
    wxLines.push(
      `\u2022 **${p.name}:** ${p.temp}${p.unit} - ${p.short}` +
        (p.wind ? ` - wind ${p.wind}` : ""),
    );
  }
  wxLines.push(
    `\u2022 **Source:** ${weather?.source || "NWS"} (${weather?.city || "Mountain View"}, ${weather?.state || "HI"})`,
  );
  if (Array.isArray(weather?.alerts) && weather.alerts.length) {
    for (const a of weather.alerts.slice(0, 4)) {
      wxLines.push(
        `\u2022 **HAZARD:** ${a.event}${a.severity ? ` (${a.severity})` : ""}`,
      );
    }
  } else {
    wxLines.push(`\u2022 **Hazards:** none active (NWS)`);
  }

  const content = [
    `**Host site** - Hawaii Mountain View (Starlink / solar)`,
    `**Solar / EcoFlow**`,
    ...solarLines,
    `**Local weather**`,
    ...wxLines,
  ].join("\n");

  return {
    content,
    detail: `host-site solar=${solarLines.length} wx=${weather?.ok ? "ok" : "fail"} alerts=${weather?.alerts?.length || 0}`,
  };
}

export async function handleHostSiteRoutes(
  req: Request,
  env: HostSiteEnv,
  subpath: string,
): Promise<Response | null> {
  if (!subpath.startsWith("/rootmc/host-site")) return null;
  const rest = subpath.slice("/rootmc/host-site".length) || "/";

  if (req.method === "GET" && (rest === "/telemetry" || rest === "/")) {
    const telem = await readHostSiteTelemetry(env.DB);
    return json({ ok: true, telemetry: telem });
  }

  if (req.method === "POST" && rest === "/telemetry") {
    if (!workstationKeyOk(env, req)) {
      return json({ ok: false, detail: "unauthorized" }, 401);
    }
    let body: any;
    try {
      body = await req.json();
    } catch {
      return json({ ok: false, detail: "invalid_json" }, 400);
    }
    await ensureTable(env.DB);
    const now = new Date().toISOString();
    await env.DB.prepare(
      `INSERT INTO rootmc_host_site_telemetry (host_key, payload_json, updated_at)
       VALUES (?, ?, ?)
       ON CONFLICT(host_key) DO UPDATE SET
         payload_json = excluded.payload_json,
         updated_at = excluded.updated_at`,
    )
      .bind("primary", JSON.stringify(body), now)
      .run();
    return json({ ok: true, updated_at: now });
  }

  return null;
}

