/**
 * Build a short hour-recap body from status events (last `windowMs`).
 */
export function buildHourRecapText({ windowMs = 60 * 60 * 1000, now = Date.now() } = {}) {
  const since = now - windowMs;
  const events = loadStatusEvents(80)
    .map(parseEventLine)
    .filter((e) => e && e.at >= since);

  const buckets = new Map();
  for (const e of events) {
    const label = bucketLabel(e.text);
    if (!label) continue;
    if (!buckets.has(label)) buckets.set(label, []);
    const list = buckets.get(label);
    if (list.length < 4) list.push(e.text.slice(0, 120));
  }

  const hours = Math.round(windowMs / 3600_000) || 1;
  const lines = [
    `**Ava hour recap** (~last ${hours}h)`,
    "",
  ];

  if (!buckets.size) {
    lines.push("- Quiet on internal status log — replies may still have landed via Cursor / catch-up.");
  } else {
    for (const [label, items] of buckets) {
      lines.push(`- **${label}:** ${items.length} event(s)`);
      for (const item of items.slice(0, 2)) {
        lines.push(`  - ${item}`);
      }
    }
  }

  lines.push("");
  lines.push(
    "_Auto-posted each hour when live. Ask me anytime for a fresh dig. Host locale stays private._",
  );
  lines.push("");
  lines.push("- Ava");

  return scrubPublicReply(lines.join("\n"), { surface: "discord" });
}

