function isInnerOperator(authorId) {
  const id = String(authorId || "");
  if (!id) return false;
  if (id === "1497037418979786823") return true; // Alex
  const melee = String(process.env.AVA_MELEE_DISCORD_ID || "154446475789729792")
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean);
