import { loadEnv, botToken, AVA_CHANNELS } from "../src/config.mjs";
import { editMessage } from "../src/discordApi.mjs";

function scrub(text) {
  let next = String(text || "");
  const before = next;
  next = next.replace(/(?:^|\n)[•\-*]\s*Manipulation gate[^\n]*/gi, "");
  next = next.replace(/,\s*manipulation gate(?=,|\s)/gi, "");
  next = next.replace(/\(manipulation gate,\s*/gi, "(");
  next = next.replace(/\n{3,}/g, "\n\n").trimEnd();
  return next === before ? null : next;
}

async function fetchJson(token, path, opts = {}) {
  const res = await fetch(`https://discord.com/api/v10${path}`, {
    ...opts,
    headers: {
      Authorization: `Bot ${token}`,
      "Content-Type": "application/json",
      ...(opts.headers || {}),
    },
  });
  if (!res.ok) throw new Error(`${res.status} ${await res.text()}`);
  if (res.status === 204) return null;
  return res.json();
}

const env = await loadEnv();
const tok = botToken(env);
let edited = 0;
for (const [name, id] of [
  ["updates", AVA_CHANNELS.updates],
  ["admins", AVA_CHANNELS.admins],
]) {
  let before = "";
  let found = 0;
  for (let page = 0; page < 12; page++) {
    const q = `/channels/${id}/messages?limit=100${before ? `&before=${before}` : ""}`;
    const msgs = await fetchJson(tok, q);
    if (!Array.isArray(msgs) || !msgs.length) break;
    for (const m of msgs) {
      if (!/manipulation gate/i.test(m.content || "")) continue;
      found += 1;
      const cleaned = scrub(m.content);
      if (!cleaned) continue;
      await editMessage((p, o) => fetchJson(tok, p, o), id, m.id, cleaned);
      edited += 1;
      console.log("edited", name, m.id);
    }
    before = msgs[msgs.length - 1].id;
  }
  console.log(name, "found", found);
}
console.log({ edited });

